public static void replaceNode(Name _collectorName, TFMProcess _process, int _track, int _newID)
{
    TFMProcessCollectorDeviations   deviation;

    ttsbegin;
    select forupdate firstonly deviation where deviation.collectorName == _collectorName && deviation.ProcessID == _process.parmProcessName() && deviation.Version == _process.parmVersion() && deviation.TrackNo == _track;

    deviation.collectorName = _collectorName;
    deviation.ProcessID = _process.parmProcessName();
    deviation.Version = _process.parmVersion();
    deviation.TrackNo = _track;
    deviation.newID = _newID;
    deviation.write();

    ttscommit;
}

public static int collectorOverrideID(Name _collectorName, TFMProcess _process, int _track)
{
    TFMProcessCollectorDeviations   deviation;

    select firstonly deviation where deviation.collectorName == _collectorName && deviation.ProcessID == _process.parmProcessName() && deviation.Version == _process.parmVersion() && deviation.TrackNo == _track;
    return deviation.newID;        
}

public static void IncrementVersion(TFMProcessID _processID, Version _fromVersion, Version _toVersion)
{

    TFMProcessCollectorDeviations deviation;

    while select deviation where deviation.ProcessID == _processID && deviation.Version == _fromVersion
    {
        deviation.Version           = _toVersion;
        deviation.insert();
    }

}
